245→          } else {
246→            rawText = new TextDecoder("utf-8", { fatal: false }).decode(buffer).slice(0, 10000);
247→          }
248→          await supabase.from("resumes").update({ parsed_text: rawText }).eq("id", rid);
249→        }
250→      }
251→
252→      if (!rawText) {
253→        await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
254→        continue;
255→      }
256→
257→      // LLM parse call for structured JSON
258→      try {
259→        const parsed = await parseResumeWithLLM(rawText, cfg, resumeParsePrompt);
260→        await supabase.from("resumes").update({
261→          parsed_json: parsed,
262→          parse_version: CURRENT_PARSE_VERSION,
263→          parsed_at: new Date().toISOString(),
264→          candidate_name: parsed.candidate_name || resume.candidate_name,
265→        } as any).eq("id", rid);
266→      } catch (err) {
267→        console.error(`Failed to parse resume ${rid}:`, err);
268→        await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
269→      }
270→    }
271→
272→    // ─── STEP 2: Generate embeddings (cached) ─────────────────────
273→    console.log("Generating embeddings...");
274→    const { data: resumesForEmbedding } = await supabase
275→      .from("resumes")
276→      .select("id, parsed_json, embedding, parsed_text")
277→      .in("id", targetResumeIds);
278→
279→    const needEmbedding = (resumesForEmbedding || []).filter((r: any) => !r.embedding && (r.parsed_json || r.parsed_text));
280→    if (needEmbedding.length > 0) {
281→      // Build summaries for embedding (from parsed_json to reduce injection)
282→      const summaries = needEmbedding.map((r: any) => {
283→        if (r.parsed_json) {
284→          const p = r.parsed_json;
285→          const parts: string[] = [];
286→          if (p.candidate_name) parts.push(p.candidate_name);
287→          if (p.skills_with_evidence) parts.push(`Skills: ${p.skills_with_evidence.map((s: any) => typeof s === 'string' ? s : s.skill || s.name || '').join(', ')}`);
288→          if (p.tools) parts.push(`Tools: ${p.tools.join(', ')}`);
