290→          if (p.roles_with_dates) parts.push(`Roles: ${p.roles_with_dates.map((r: any) => `${r.title || r.role || ''} at ${r.company || ''}`).join('; ')}`);
291→          if (p.education) parts.push(`Education: ${p.education.map((e: any) => typeof e === 'string' ? e : `${e.degree || ''} ${e.institution || ''}`).join('; ')}`);
292→          return parts.join('. ').slice(0, 4000);
293→        }
294→        return (r.parsed_text || '').slice(0, 4000);
295→      });
