 58→const Index = () => {
 59→  const { user } = useAuth();
 60→
 61→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 62→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 63→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 64→  const [results, setResults] = useState<Result[]>([]);
 65→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 66→  const [authOpen, setAuthOpen] = useState(false);
 67→
 68→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 69→
 70→  const fetchPastJobs = useCallback(async () => {
 71→    if (!user) return;
 72→    setLoadingPastJobs(true);
 73→    try {
 74→      const { data: jobs } = await supabase
 75→        .from("jobs")
 76→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 77→        .eq("user_id", user.id)
 78→        .order("created_at", { ascending: false })
 79→        .limit(50);
 80→      if (jobs) {
 81→        setPastJobs(jobs.map((j: any) => ({
 82→          id: j.id,
 83→          title: j.title,
 84→          job_description: j.job_description,
 85→          status: j.status,
 86→          created_at: j.created_at,
 87→          resume_count: j.resumes?.[0]?.count ?? 0,
 88→          jd_analysis_json: j.jd_analysis_json,
 89→          dynamic_weights_json: j.dynamic_weights_json,
 90→          inbox_email: j.inbox_email ?? null,
 91→        })));
 92→      }
 93→    } catch (err) {
 94→      console.error("Failed to load past jobs:", err);
 95→    } finally {
 96→      setLoadingPastJobs(false);
 97→    }
 98→  }, [user]);
 99→
100→  useEffect(() => {
101→    fetchPastJobs();
102→  }, [fetchPastJobs]);
103→
104→  const loadJobData = async (jobId: string) => {
105→    setSelectedJobId(jobId);
106→    try {
107→      const [resumesRes, resumeListRes] = await Promise.all([
108→        supabase
109→          .from("resumes")
110→          .select("id, filename, file_path, candidate_name, created_at")
111→          .eq("job_id", jobId)
112→          .order("created_at", { ascending: false }),
113→        supabase
114→          .from("resumes")
115→          .select("id, filename, file_path, candidate_name, parsed_json")
116→          .eq("job_id", jobId),
117→      ]);
118→
119→      const resumes = resumesRes.data ?? [];
120→      setExistingResumes(resumes);
121→
122→      const resumeData = (resumeListRes.data ?? []) as Array<{
123→        id: string;
124→        filename: string;
125→        file_path: string | null;
126→        candidate_name: string | null;
127→        parsed_json?: any;
128→      }>;
129→      if (resumeData.length === 0) {
130→        setResults([]);
131→        return;
132→      }
133→
134→      const resumeIds = resumeData.map((r) => r.id);
135→      const { data: resultData } = await supabase
136→        .from("results")
137→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
138→        .in("resume_id", resumeIds);
139→
140→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
141→      const merged: Result[] = (resultData ?? []).map((r: any) => {
142→        const resume = resumeMap.get(r.resume_id);
143→        const parsed = resume?.parsed_json as any;
144→        return {
145→          ...r,
146→          overall_score: r.overall_score ?? 0,
147→          missing_skills: r.missing_skills ?? [],
148→          filename: resume?.filename ?? "Unknown",
149→          file_path: resume?.file_path ?? null,
150→          candidate_name: resume?.candidate_name ?? null,
151→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
152→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
153→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
154→          parsed_json: resume?.parsed_json ?? null,
155→        };
156→      });
157→      merged.sort((a, b) => b.overall_score - a.overall_score);
158→      setResults(merged);
159→    } catch (err) {
160→      console.error("Failed to load job data:", err);
161→      toast.error("Failed to load job data");
162→    }
163→  };
164→
165→  const handleNewJob = () => {
166→    setSelectedJobId(null);
167→    setResults([]);
168→    setExistingResumes([]);
169→  };
170→
171→  const handleJobCreated = (job: PastJob) => {
172→    setPastJobs((prev) => [job, ...prev]);
173→    setSelectedJobId(job.id);
174→    loadJobData(job.id);
175→  };
176→
177→  const handleRenameJob = (jobId: string, newTitle: string) => {
178→    setPastJobs((prev) =>
179→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
180→    );
181→  };
182→
183→  const handleDeleteJob = async (jobId: string) => {
184→    try {
185→      await supabase.from("resumes").delete().eq("job_id", jobId);
186→      await supabase.from("jobs").delete().eq("id", jobId);
187→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
188→      if (selectedJobId === jobId) handleNewJob();
189→      toast.success("Job deleted");
190→    } catch {
191→      toast.error("Failed to delete job");
192→    }
193→  };
194→
195→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
196→    setPastJobs((prev) =>
197→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
198→    );
199→  };
200→
201→  const requireAuth = useCallback(() => {
202→    if (!user) { setAuthOpen(true); return true; }
203→    return false;
204→  }, [user]);
205→
206→  return (
207→    <SidebarProvider className="h-svh overflow-hidden">
208→      <JobSidebar
209→        pastJobs={pastJobs}
210→        selectedJobId={selectedJobId}
211→        loadingPastJobs={loadingPastJobs}
212→        onSelectJob={loadJobData}
213→        onNewJob={handleNewJob}
214→        onRenameJob={handleRenameJob}
215→        onDeleteJob={handleDeleteJob}
216→        onAuthRequired={() => setAuthOpen(true)}
217→        isAuthenticated={!!user}
218→      />
219→
220→      <SidebarInset className="h-svh overflow-y-auto">
221→        <AppHeader />
222→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
223→          <SidebarTrigger />
224→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
225→        </div>
226→        <JobDetailView
227→          selectedJobId={selectedJobId}
228→          selectedJob={selectedJob}
229→          results={results}
230→          setResults={setResults}
231→          existingResumes={existingResumes}
232→          setExistingResumes={setExistingResumes}
233→          onJobCreated={handleJobCreated}
234→          onAuthRequired={() => setAuthOpen(true)}
235→          isAuthenticated={!!user}
236→          onJobUpdated={handleJobUpdated}
237→        />
238→      </SidebarInset>
239→
240→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
241→    </SidebarProvider>
242→  );
243→};
244→
245→export default Index;
