 58→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 59→  if (score >= 70) return { label: "Strong", variant: "success" };
 60→  if (score >= 40) return { label: "Good", variant: "warning" };
 61→  return { label: "Weak", variant: "destructive" };
 62→};
