115→
116→CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)
117→RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
118→  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role)
119→$$;
120→
121→CREATE OR REPLACE FUNCTION public.is_job_owner(_user_id UUID, _job_id UUID)
122→RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
123→  SELECT EXISTS (SELECT 1 FROM public.jobs WHERE id = _job_id AND user_id = _user_id)
124→$$;
125→
126→CREATE OR REPLACE FUNCTION public.deduct_credits(_user_id UUID, _job_id UUID, _amount INTEGER)
127→RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
128→DECLARE current_credits INTEGER;
129→BEGIN
130→  SELECT credits INTO current_credits FROM public.profiles WHERE user_id = _user_id FOR UPDATE;
131→  IF current_credits IS NULL OR current_credits < _amount THEN RETURN FALSE; END IF;
132→  UPDATE public.profiles SET credits = credits - _amount, updated_at = now() WHERE user_id = _user_id;
133→  INSERT INTO public.usage_logs (user_id, job_id, credits_used) VALUES (_user_id, _job_id, _amount);
134→  RETURN TRUE;
135→END;
136→$$;
137→
138→CREATE OR REPLACE FUNCTION public.update_updated_at_column()
139→RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
140→BEGIN NEW.updated_at = now(); RETURN NEW; END;
141→$$;
