147→CREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
148→CREATE TRIGGER update_platform_config_updated_at BEFORE UPDATE ON public.platform_config FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
149→
150→CREATE OR REPLACE FUNCTION public.handle_new_user()
151→RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
152→BEGIN
153→  INSERT INTO public.profiles (user_id, inbox_email) VALUES (NEW.id, encode(gen_random_bytes(8), 'hex') || '@inbound.instantranker.com');
154→  INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'user');
155→  RETURN NEW;
156→END;
157→$$;
158→
159→CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
